define(["editor_tiny/utils","core/str","tiny_zoomclassroom/common","tiny_zoomclassroom/ui","tiny_zoomclassroom/options"],function(Utils,Str,Common,Ui,Options){const getSetup=async()=>{const[buttonImage,menuText]=await Promise.all([Utils.getButtonImage("icon",Common.component),Str.get_string("menuitem",Common.component)]);return editor=>{if(!Options.getTool(editor)){return;}editor.ui.registry.addIcon(Common.icon,buttonImage.html);editor.ui.registry.addButton(Common.buttonName,{icon:Common.icon,tooltip:menuText,onAction:()=>Ui.handleAction(editor)});editor.ui.registry.addMenuItem(Common.buttonName,{icon:Common.icon,text:menuText,onAction:()=>Ui.handleAction(editor)});};};return{getSetup:getSetup};});
